// Open opens the SQLite database at dsn, sets WAL journal mode, runs the
// idempotent schema migrations (all §9.1 tables + §9.2 generated columns and
// indexes), and returns a *Store. It is safe to call Open on an existing
// database: every migration statement is CREATE ... IF NOT EXISTS.
func Open(ctx context.Context, dsn string) (*Store, error) {
	db, err := sql.Open(sqliteDriver, dsn)
	if err != nil {
		return nil, fmt.Errorf("store: open %q: %w", dsn, err)
	}
	if _, err := db.ExecContext(ctx, "PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("store: set WAL: %w", err)
	}
	for _, stmt := range schemaSQL {
		if _, err := db.ExecContext(ctx, stmt); err != nil {
			db.Close()
			return nil, fmt.Errorf("store: migrate: %w", err)
		}
	}
	return &Store{db: db}, nil
}

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// DB returns the underlying *sql.DB. Store stays the sole OPENER and CLOSER of
// the connection; this accessor only shares the live handle with trusted
// internal consumers (internal/module) so they can run their own parameterized
// reads of tables store does not expose methods for. Callers MUST NOT call
// sql.Open or Close on it. (Seam S10: module owns its SELECT, store owns the
// connection.)
func (s *Store) DB() *sql.DB { return s.db }

// formatTime renders a timestamp as the RFC3339Nano TEXT value persisted in
// §9.1 TEXT columns. It is round-trip-stable with parseTime.
func formatTime(t time.Time) string { return t.UTC().Format(time.RFC3339Nano) }

// parseTime reads an RFC3339Nano TEXT value back into a time.Time.
func parseTime(s string) (time.Time, error) { return time.Parse(time.RFC3339Nano, s) }
